const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat \"$STAMPED_ASSESSMENT_VERSION\"; cat \"$STAMPED_DELIVERY_MANIFEST\"; cat \"$STAMPED_WORKER_STOP_RECEIPT\"; cat \"$STAMPED_JUDGE_OUTPUT/judge-target.json\"",max_output_tokens:10000}),
  tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" --help",max_output_tokens:4000}),
  tools.exec_command({cmd:"rg --files \"$STAMPED_JUDGE_TARGET\" | sort | head -250",max_output_tokens:7000})
]);
for (const r of results) text(r.status==="fulfilled"?r.value.output:("ERROR "+r.reason));

