const r = await tools.exec_command({cmd:"cat > /tmp/verify_delivery.py <<'PY'
import json, os, hashlib, stat
m=json.load(open(os.environ['STAMPED_DELIVERY_MANIFEST']))
root=os.environ['STAMPED_JUDGE_TARGET']
entries=[e for e in m['entries'] if e['path'].startswith('content/workspace/') or e['path']=='content/workspace']
problems=[]
for e in entries:
 p=os.path.join(root,e['path'].removeprefix('content/workspace').lstrip('/'))
 try: st=os.lstat(p)
 except FileNotFoundError: problems.append(('missing',e['path']));continue
 if e['kind']=='directory':
  if not stat.S_ISDIR(st.st_mode): problems.append(('kind',e['path']))
 elif e['kind']=='file':
  if not stat.S_ISREG(st.st_mode): problems.append(('kind',e['path']));continue
  b=open(p,'rb').read()
  if hashlib.sha256(b).hexdigest()!=e.get('sha256'): problems.append(('sha256',e['path']))
  if len(b)!=e.get('size'):problems.append(('size',e['path']))
 elif e['kind']=='symlink':
  if not stat.S_ISLNK(st.st_mode): problems.append(('kind',e['path']));continue
  link=os.readlink(p)
  if link!=e.get('target'): problems.append(('link',e['path'],link,e.get('target')))
print(json.dumps({'entries_checked':len(entries),'mismatches':problems[:100],'mismatch_count':len(problems)},indent=2))
PY
